insert into public.listings (id, dealer_id, imported_by, import_job_id, source_url, brand, model, reference, year, caliber, case_size_mm, condition, has_box, has_papers, price_cents, currency, description, status, created_at, winding, case_material, dial_color, style, complications, brand_key, sold_at, availability_checked_at, edited_fields) values
  ('2d51395e-781a-4ab3-8147-faf628003622', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1940s-breguet-rattrapante-split-seconds-chronograph-pocket-watch-in-steel', 'Breguet', 'Rattrapante', null, 1946, '19 lignes chronograph', 50, null, true, null, 1689500, 'USD', 'This 1940s Breguet Rattrapante Pocket Watch features a large 50mm stainless steel case and a flawless enamel dial with printed Breguet numerals. It was sold to the French Aeronautics division in November 1946 and is powered by a 19 lignes chronograph caliber.', 'active', '2026-09-14T15:48:15.204512+00:00', null, 'steel', 'white', 'pocket', array['chronograph']::complication[], 'breguet', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('3db5a1c4-36c5-41d6-8f91-35e205b7c9b2', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1960s-omega-speedmaster-professional-ref-145022-69ba', 'Omega', 'Speedmaster Professional', '145.022-69BA', 1960, '861', null, null, null, null, 3699500, 'USD', 'A special and rare 1960’s Omega Speedmaster Professional in solid 18K YG, made in limited quantities with only 1014 ever crafted. This example is an early numbered under 40, so very close to the original 32 that were gifted.', 'active', '2026-09-14T15:48:19.295919+00:00', 'manual', 'yellow_gold', null, 'other', '{}'::complication[], 'omega', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('5a528331-82e4-40de-a53a-f56094f25ed8', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1970s-vacheron-constantin-automatic-screwback-calatrava-ref-6394', 'Vacheron Constantin', 'Calatrava', '6394', 1970, 'Cal. K1072/1', null, null, null, null, 2699500, 'USD', 'This is a 1970s Vacheron & Constantin Dress Watch ref. 6394 featuring a linen textured dial with applied gold indices filled with onyx and a stepped florentine screwback case.', 'active', '2026-09-14T15:48:15.958001+00:00', 'automatic', 'yellow_gold', 'white', 'dress', '{}'::complication[], 'vacheronconstantin', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('5cde8e19-188e-4757-84be-57423c18f82d', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1950s-audemars-piguet-cioccolatone-18k-pink-gold', 'Audemars Piguet', 'Cioccolatone', null, 1950, 'Cal. 2001', 33, null, null, null, 1939500, 'USD', 'This is a handsome 1950s Audemars Piguet “Cioccolatone” in an 18K rose gold case with a silvered dial and applied rose Arabic numerals. It is powered by the manually wound Audemars Piguet caliber 2001.', 'active', '2026-09-14T15:48:24.699019+00:00', 'manual', 'rose_gold', 'silver', 'dress', '{}'::complication[], 'audemarspiguet', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('7589cd6a-8a8e-4671-b850-67f25681d1c9', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1950s-e-gbelin-jumbo-clamshell-chronograph-valjoux-21', 'E. Gübelin', 'Jumbo Clamshell', null, 1950, 'Valjoux 21', 38, null, null, null, 999500, 'USD', 'An awesome and rare 1950s Jumbo Clamshell Chronograph for Gübelin, in a sharp 38mm stainless steel case with gold radial foiled indices and matching gold handset.', 'active', '2026-09-14T15:48:19.269178+00:00', null, 'steel', null, 'chronograph', array['chronograph']::complication[], 'egubelin', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('962d0a1d-77eb-4ac0-b5e7-62e1aede733f', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1980s-gerald-genta-broad-arrow-dress-watch-18k-yg', 'Gerald Genta', 'Broad Arrow', null, 1980, 'quartz', 30, null, null, null, 389500, 'USD', 'A nutty 1980s creation by Gerald Genta featuring a 30mm solid 18K yellow gold case with ribbed midcase and a deeply stepped dial with exaggerated broad arrow hands. Its Genta signed quartz caliber is running well with a fresh battery.', 'active', '2026-09-14T15:48:24.403591+00:00', 'quartz', 'yellow_gold', null, 'dress', '{}'::complication[], 'geraldgenta', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('cfdb493b-8a7f-4f33-8695-3aa487ec242b', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1960s-patek-philippe-calatrava-ref-3426-on-gay-freres-bracelet', 'Patek Philippe', 'Calatrava', '3426', 1960, '23-300', 32, null, null, null, 1995000, 'USD', 'This is a 1960s Patek Philippe Calatrava ref. 3426 with a 32mm 18K yellow gold case and a linen dial. It features a manually wound Patek caliber 23-300 and is paired with a heavy Gay Freres bracelet.', 'active', '2026-09-14T15:48:20.637251+00:00', 'manual', 'yellow_gold', 'white', 'dress', '{}'::complication[], 'patekphilippe', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('daf45b0f-2556-4318-9ebb-912452c8f847', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1960s-movado-bull-horn-dress-watch-ref-5036-18k-yg', 'Movado', 'Bull Horn', '5036', 1960, 'Cal. 1156', 33, null, null, null, 539500, 'USD', 'This is a rare 1960s Movado dress watch with a unique ''Bull Horn'' design and a textured art deco bezel. It features a minimalist champagne dial and is powered by a manually wound Movado caliber 1156.', 'active', '2026-09-14T15:48:15.844661+00:00', 'manual', 'yellow_gold', 'champagne', 'dress', '{}'::complication[], 'movado', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('e52a3f9b-c4b6-4585-843c-cad588446204', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1950s-universal-genve-cioccolatone-w-clous-de-paris-dial-18k-pink-gold', 'Universal Genève', 'Cioccolatone', null, 1950, 'UG', 36, null, null, null, 599500, 'USD', 'This is a 1950s Universal Genève Cioccolatone in 18K Rose Gold with a Clous De Paris guilloche dial. It has a manually wound UG caliber and measures 36mm x 25mm.', 'active', '2026-09-14T15:48:17.782163+00:00', 'manual', 'rose_gold', null, 'dress', '{}'::complication[], 'universalgeneve', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[]),
  ('5f8d946d-6c44-44b9-95ce-670c16a795f9', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', '5eed0000-0000-4000-8000-000000000001', null, 'https://www.goldfingersvintage.com/watches/p/1970s-patek-philippe-ref-3633-w-onyx-stone-dial-18k-yg', 'Patek Philippe', 'ref. 3633', '3633', 1970, 'cal. 177', 34, null, null, null, 3999500, 'USD', 'This Patek Philippe ref. 3633 from the 1970s features a ribbed texture 18K yellow gold case and a flawless black Onyx stone dial. It has a manually wound Patek cal. 177 movement that is running well.', 'active', '2026-09-14T15:48:15.106255+00:00', 'manual', 'yellow_gold', 'black', 'dress', '{}'::complication[], 'patekphilippe', null, '2026-09-16T06:26:50.423272+00:00', '{}'::text[])
