  ('60fef02e-f850-4d62-b168-299f0fb0c077', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6aa1d14da60b5f204466cbcf', 'https://www.goldfingersvintage.com/watches/p/1940s-breguet-rattrapante-split-seconds-chronograph-pocket-watch-in-steel', '{"text":"A superb and rare 1940s Breguet Rattrapante Pocket Watch in a large 50mm stainless steel case sporting a flawless enamel dial adorned with printed breguet numerals, sold to the French Aeronautics division, à l’Aéronautique, in November 1946, powered by a gorgeous 19 lignes chronograph caliber with split seconds complication, its numbered dial, caseback and movement all matching, paired with its correct and likely original box.","title":"1940''s Breguet Rattrapante Split-Seconds Chronograph Pocket Watch in Steel","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/922e4fc6-ec9e-4404-84d7-305c43ddad3d/B0006384.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/91b8d2e2-d6bd-4f99-9713-97d0c07c8875/B0006404.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e9ca9547-67be-4be6-9e98-7e5e62c23a84/B0006376.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1bac26e7-2b74-42e1-a5b9-8eb0606a0eeb/B0006395.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/fba36f01-65f4-4794-aacb-f27b1a3a0c85/B0006398.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0d122adc-9254-49c9-9553-23864ccbdc34/B0006399.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/890f0c2a-c1dc-4a9b-af7c-345d736c298f/B0006393.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b244213d-6bce-44d6-8f7c-dc4631149549/B0006414.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1940s-breguet-rattrapante-split-seconds-chronograph-pocket-watch-in-steel","externalId":"squarespace:6aa1d14da60b5f204466cbcf","priceCents":1689500}'::jsonb, 'f622abd2553390f1d29bddc8799d782782168e2400259c6c7f6e7508509c6f20', 'd6144ddebeabaf34c0f5b3573f16f099e95f9d0225aa9494cf9faeb9017680ac', true, true, '{"year":1946,"brand":"Breguet","model":"Rattrapante","style":"pocket","caliber":"19 lignes chronograph","has_box":true,"winding":null,"currency":"USD","brand_key":"breguet","condition":null,"reference":null,"dial_color":"white","has_papers":null,"description":"This 1940s Breguet Rattrapante Pocket Watch features a large 50mm stainless steel case and a flawless enamel dial with printed Breguet numerals. It was sold to the French Aeronautics division in November 1946 and is powered by a 19 lignes chronograph caliber.","price_cents":1689500,"case_size_mm":50,"case_material":"steel","complications":["chronograph"]}'::jsonb, 'f622abd2553390f1d29bddc8799d782782168e2400259c6c7f6e7508509c6f20', 'd6144ddebeabaf34c0f5b3573f16f099e95f9d0225aa9494cf9faeb9017680ac', 'be2e95b07d39c129986a936fc39471c1a51e6b5c7fed6e15186a9bb4921c23a8', null, '2d51395e-781a-4ab3-8147-faf628003622', '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('c2769f7e-3c8f-4912-aa1c-33be9dbc91e6', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a96045758cbf6266d65b784', 'https://www.goldfingersvintage.com/watches/p/1960s-omega-speedmaster-professional-ref-145022-69ba', '{"text":"A special and rare 1960’s Omega Speedmaster Professional in solid 18K YG, made in limited quantities with only 1014 ever crafted, the first 33 of which were gifted to astronauts, celebrities and important members of program, the remaining were sold at retail. The example here, in fantastic condition, with sharp bezel, twisted lugs retaining its factory brushing, signed Omega crown and signed crystal, is an early numbered under 40, so very close to the original 32 that were gifted. \n Its 861 Omega caliber is running well and keeping accurate time.","title":"1960''s Omega Speedmaster Professional ref. 145.022-69BA","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0da963d9-1f17-4c0f-a56f-007e28c0d9ea/B0006036.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/9ebe9090-c3b6-4c01-97b8-d1ad562a726d/B0006038.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/cb686bb6-36a1-4f51-bdff-4177bbfdb006/B0006041.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/96b0899f-a4a1-4d88-a23b-be578f8bdd91/B0006049.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/937102a7-a054-411a-ac05-9dd1d2d1e456/B0006052.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d2d85eb1-0a54-4f7a-abd0-19ebc402f52c/B0006055.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1960s-omega-speedmaster-professional-ref-145022-69ba","externalId":"squarespace:6a96045758cbf6266d65b784","priceCents":3699500}'::jsonb, '476fa9112ea4a0e8992ee4a6e177b55ae642beefe4f091b4e83b808b95076e37', '9