  ('d2f81c71-af2e-4d45-ad44-c63f723c51ed', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a68f3876e06c124b8ee27cd', 'https://www.goldfingersvintage.com/watches/p/1950s-e-gbelin-jumbo-clamshell-chronograph-valjoux-21', '{"text":"An awesome and rare 1950s Jumbo Clamshell Chronograph for Gübelin, in a sharp 38mm stainless steel case, gold radial foiled indices with matching gold handset, with a serpentine at 6, this Valjoux 21 powered Chronograph is a sum of a very seldom seen combination of traits that make it way more watch than its price suggests.","title":"1950''s E. Gübelin Jumbo Clamshell Chronograph Valjoux 21","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/29a893e9-f107-4e81-84a7-1ee9d845dd3a/B0004586.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/8df365e0-b681-4331-827e-cfb617ea48ad/B0004593.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4276ad77-87e6-4b9c-b8ee-4d8058d3d37e/B0004632.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b463dbde-9716-42a1-a991-c4f2283c7786/B0004605.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/29e8aee6-f302-4f58-972c-c90e12925106/B0004627.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/10256f61-da43-4b13-859d-aaae921fd197/B0004624.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/05069f34-ef33-41a4-951a-f494428c4eda/B0004621.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0fdbf397-f49b-432e-8080-9c9d2d128956/B0004617.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/01c9a34a-8384-4e15-8082-c03f37b750a2/B0004614.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/823f881c-dfa