  ('97b14d51-39b5-478d-b669-dbe1eddac1d4', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a5fb7911b9743318ccefbab', 'https://www.goldfingersvintage.com/watches/p/1960s-movado-m90-breguet-chronograph-ref-19048-w-gay-freres-bracelet-unpolished', '{"text":"An extremely handsome and uncommon 1960s Movado M90 Chronograph ref. 19048 in an unpolished 35mm Francois Borgel screwback case with a beautiful dial with gold applied Breguet numerals, matching sword hands and the brands iconic serpentine chronograph hand, this is example paired on a rare and period correct stretch rivet Gay Freres bracelet. \nIt’s manually wound F. Piguet based in house modified M90 chronograph module is running and functioning well. We do not have service history.","title":"1960''s Movado M90 \"Breguet\" Chronograph ref. 19048 w/ Gay Freres Bracelet *Unpolished*","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7e6db11f-0fb7-4ebd-b4ac-b069b5ffb77b/B0004116.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1822ef30-1a20-4a84-b4f6-da4cbd43b752/B0004138.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/977f0208-4f62-48ab-8406-22521baf9845/B0004121.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/eacabe00-455e-404e-a9f9-07a44dd93ff8/B0004165.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4fb04539-2748-4d34-b9ab-f27cebf08794/B0004160.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/221286cf-9ae0-4600-9be9-cebd337237dc/B0004155.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f092e75d-f1ac-4083-b5a7-2aa80b07f96b/B0004147.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/dc11840a-130a-4f87-9cf8-245ef8083902/B0004143.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ac59275a-800f-422f-9ed3-979828b337e3/B0004141.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/024e6577-2fbe-4a81-a726-d177d6392d57/B0004134.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1960s-movado-m90-breguet-chronograph-ref-19048-w-gay-freres-bracelet-unpolished","externalId":"squarespace:6a5fb7911b9743318ccefbab","priceCents":1699500}'::jsonb, '427ad44dc2fa8dbf71acf5c3e3f7726f8d6fc738ad1d80c1fe1db01175e90ac9', '12546d09deedffde8893fea7a86267e98fe1dacb8a322c9e650fda52bd87c50b', true, false, '{"year":1960,"brand":"Movado","model":"M90","style":"chronograph","caliber":"F. Piguet","has_box":null,"winding":"manual","currency":"USD","brand_key":"movado","condition":null,"reference":"19048","dial_color":"other","has_papers":null,"description":"An uncommon 1960s Movado M90 Chronograph ref. 19048 with a beautiful dial featuring gold Breguet numerals and a matching sword hands. It has a manually wound F. Piguet based movement and comes on a period correct Gay Freres bracelet.","price_cents":1699500,"case_size_mm":35,"case_material":"other","complications":["chronograph"]}'::jsonb, '427ad44dc2fa8dbf71acf5c3e3f7726f8d6fc738ad1d80c1fe1db01175e90ac9', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('2ca61571-8484-40fe-8645-bc8aa34daf0e', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a53ed306d53a147293a3799', 'https://www.goldfingersvintage.com/watches/p/1970s-patek-philippe-ref-3566-full-collectors-set', '{"text":"A very special 1970s Patek Philippe ref. 3566 in 18K white gold with a sunburst blue dial, in nearly mint condition, this example comes as full original collectors set with boxes, strap, hangtag, buckle and original papers as sold by G&uuml;belin in Geneva in 1977. \nThis is a true time capsule for someone looking for everything.","title":"1970''s Patek Philippe ref. 3566 Full Collectors Set","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1b3cf595-ce41-4710-b5cc-afce20f380ca/B0003566.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/9d1ea4ac-6af2-45a2-bb12-8419542d493b/B0003575.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d1812bdd-6539-4783-94e8-bb0f33db344f/B0003578.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f14127c4-be03-4540-b93f-c0622d7f312b/B0003585.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/24a5b2c6-4ec2-4ee3-b39e-af03d13c01c6/B0003597.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/fe1e77ee-7f1a-4d60-b563-f34e853ad6a2/B0003600.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/852e6f19-c880-412e-9dcc-6dc95d11c859/B0003603.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5677c46b-28cd-48d2-b274-c04b33fe3757/B0003610.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1970s-patek-philippe-ref-3566-full-collectors-set","externalId":"squarespace:6a53ed306d53a147293a3799","priceCents":1899500}'::jsonb, '364acb8d709dab7d40a4d0751262dd61f24ec81e77a3a702e096e96ea4e77822', 'a99f43145d92b6e960bfa9d800abbd969c005fdd73c138cdfa61eabb91dc44f6', true, false, '{"year":1977,"brand":"Patek Philippe","model":"3566","style":"dress","caliber":null,"has_box":true,"winding":null,"currency":"USD","brand_key":"patekphilippe","condition":"nearly mint","reference":"3566","dial_color":"blue","has_papers":true,"description":"This 1970s Patek Philippe ref. 3566 is made of 18K white gold and features a sunburst blue dial. It comes as a full original collectors set with boxes, strap, hangtag, buckle, and original papers.","price_cents":1899500,"case_size_mm":null,"case_material":"white_gold","complications":[]}'::jsonb, '364acb8d709dab7d40a4d0751262dd61f24ec81e77a3a702e096e96ea4e77822', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('09d968db-c2aa-4fc1-9bfa-eac99d93fccb', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a5531bbd0719241db24e00f', 'https://www.goldfingersvintage.com/watches/p/1940s-cartier-grande-normale-w-ewc-movement-extremely-rare', '{"text":"An incredibly special and very rare 1940s Cartier Grande Normale, a larger take on the classic standard size, it’s Edmond Jaeger crafted case measuring in at a proud 32x24mm with 19mm lugs, likely unpolished with sharp hallmarks and wide bevels still very present, its pad printed dial bears unmistakable and characteristic aging left to time and not disturbed by interference, paired on its period correct French made deployant, powered by a manually wound EWC movement. \nThis is a Cartier fit for the most astute collector, for one looking for the unattainable. For comparison, the standard ref. 7809 Normale measures about 30 × 23mm while the additional few millimeters on this larger case really increase the wearing experience noticeably. Its dial is completely original with amazing pad printing across its entire surface with only slight chipping around some of its edges. For a Cartier this old, its humbling to find an example this rare without any evidence of restoration. \n Its EWC signed caliber is running well and keeping accurate time. We do not have service history.","title":"1940''s Cartier Grande Normale w/ EWC Movement *Extremely Rare*","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/be35b0d1-adac-410e-bffd-aad09add4a10/B0002733.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/df4453e3-d989-4404-ab9a-107baef590c4/B0002733.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/23279f13-13c6-49d2-bf76-0cb07bc02048/B0002811.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/877b8288-fec5-496a-a319-1f0275d282f2/B0002740.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7ef4eaf7-6c4c-491d-bdeb-2afb2653ab40/B0002807.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/84897144-5fd1-4981-8f74-e90da861d216/B0002805.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e7fc4727-f931-4977-a06f-e693dee83c9d/B0002803.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/54a7e08b-247d-4022-ae94-bc2a5ed2218d/B0002800.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0d1edbe8-684c-4b0c-b67c-f6e34173cdb5/B0002797.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a95bfd69-dedb-48d5-ba69-cd17302cb820/B0002793.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/729925da-ec83-49d4-b680-e01a90e8ccd5/B0002783.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/60c87d2c-5e30-48c8-8cb8-c1b225e99da7/B0002760.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1940s-cartier-grande-normale-w-ewc-movement-extremely-rare","externalId":"squarespace:6a5531bbd0719241db24e00f","priceCents":7150000}'::jsonb, 'e0384aae7f9a617b087d8ae0281ce34730db2acb8eba6715ae8f5af9458721ee', 'ff05e3ad68769394dd41fb672035dd5750a3560d252d1e30c5faebb96cc03710', true, false, '{"year":1940,"brand":"Cartier","model":"Grande Normale","style":"dress","caliber":"EWC","has_box":null,"winding":"manual","currency":"USD","brand_key":"cartier","condition":null,"reference":null,"dial_color":null,"has_papers":null,"description":"This is a very rare 1940s Cartier Grande Normale with a larger case measuring 32x24mm, powered by a manually wound EWC movement. The original dial shows characteristic aging and is paired with a period-correct deployant.","price_cents":7150000,"case_size_mm":32,"case_material":"other","complications":[]}'::jsonb, 'e0384aae7f9a617b087d8ae0281ce34730db2acb8eba6715ae8f5af9458721ee', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('7313cafe-1f4e-4f26-b9b4-17fb11fafe3e', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a552b45b48e7b64b82e1e3f', 'https://www.goldfingersvintage.com/watches/p/1940s-alpina-tank-w-black-gilt-dial-new-old-stock', '{"text":"An incredibly handsome new old stock Alpina Tank from the 1940s, in a large 38mm x 23mm stainless steel case, with hooded articulating lugs and a glossy silver gilt black dial with enough luster to light up a dark room, every bit of this watch is like new and never worn, with sharp case bevels, satin brushing and minimal dial wear, seeing a watch like this yields an appreciation for how these were meant to be experienced right from the factory. \nThis watch comes with its Alpina handle tag and while it is running well, we assume this has never been serviced and will leave as is unless requested.","title":"1940''s Alpina Tank w/ Black Gilt Dial *New Old Stock*","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/652ddc8d-78c3-4077-b789-93f2be702733/B0003613.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/02a6fb83-67a5-449d-9e25-0dd4abb476d6/B0003668.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7c18af49-a377-4416-b4ec-52cb4c9d2521/B0003654.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5ddbd7d0-b591-44ea-ae12-5760b52d67ec/B0003649.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6075fca7-0340-4053-8d35-ba4a045d7ae0/B0003646.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/124d165c-4132-4791-bdd6-fdaab1ed4b5b/B0003642.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/8c3c48bf-3890-4c73-8eb8-c944354523f5/B0003636.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5e0b70a1-a618-