  ('bd80a189-df18-4f51-8012-eaf3a0a6e49d', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a3b42beac41db618c42b33f', 'https://www.goldfingersvintage.com/watches/p/1950s-patek-philippe-ref-2950-disco-volante-retailed-by-beyer', '{"text":"A fabulous 1950s Patek Philippe ref. 2590 “Disco Volante” retailed and doubled signed by the legendary Beyer of Z&uuml;rich, whose relationship with the brand spans over two centuries, in 18K yellow gold with hidden T shaped lugs, this 34mm 18K yellow gold wristwatch wears large yet svelt on the wrist, its dial with slight aging around its perimeter, has a perfect Patek champlev&eacute; signature at 12 o’clock, and its Beyer text sharp as ever, its manually wound Patek caliber running well. \nWe filed for Patek extract and will ship to the buyer upon receipt. We do not have service history however his watch is running well.","title":"1950''s Patek Philippe ref. 2590 \"Disco Volante\" Retailed by Beyer","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/551cb113-0a2a-4472-b518-fef7d09b74d5/B0002587.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b3522266-4b18-454c-a5ea-6ddf4f3cf1a1/B0002589.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/69e05e73-dfe8-492c-b55b-7d206e8a6216/B0002600.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/776d8232-8166-48ac-9680-beee07c315ba/B0002604.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/cdb2dc17-7cda-4789-9cb5-fca1b0f21576/B0002612.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/750a28ab-cae2-4ca1-af65-a793d9f4c723/B0002628.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/471ef8f7-e723-4fa8-93c1-781869184293/B0002630.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/19305c42-de2f-4390-8745-9bd0f190ab7e/B0002637.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1950s-patek-philippe-ref-2950-disco-volante-retailed-by-beyer","externalId":"squarespace:6a3b42beac41db618c42b33f","priceCents":1399500}'::jsonb, '7d64f1120bd5a16602351d2805c7ba4483976b33fc8fa976e63d5ab42dbcf8b6', '1f1abfbb52e96f6a0463228075e4f7e2afba546e8be153e9c86fe942f6138a12', true, false, '{"year":1950,"brand":"Patek Philippe","model":"ref. 2590","style":"dress","caliber":"Patek caliber","has_box":null,"winding":"manual","currency":"USD","brand_key":"patekphilippe","condition":null,"reference":"2590","dial_color":null,"has_papers":null,"description":"This 1950s Patek Philippe ref. 2590 “Disco Volante” is in 18K yellow gold with a dial showing slight aging and a perfect Patek champlevé signature. The watch is manually wound and running well.","price_cents":1399500,"case_size_mm":34,"case_material":"yellow_gold","complications":[]}'::jsonb, '7d64f1120bd5a16602351d2805c7ba4483976b33fc8fa976e63d5ab42dbcf8b6', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('615badf5-3f4c-4a20-a61d-f88f526a068b', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69d70a1f6892561c57b59a3e', 'https://www.goldfingersvintage.com/watches/p/ef1x6crmq5q4l2dpl8rucnmej7mo6b', '{"text":"A rare masterpiece by Audemars Piguet, this important perpetual calendar pocket watch from the 1920s, crafted in a 46mm 18K white gold case, with a hand carved dial with applied breguet numerals, enamel filled dial fixtures including information displayed for day, date, month, phase of the moon and leap year, marks the pinnacle of manufacturing prowess from the maison of this era.","title":"1920’s Audemars Piguet Perpetual Calendar Pocket Watch 18K WG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1a695ebd-7ce5-4b09-acc7-76063b30e5c8/963C81B0-EBFF-4B32-A388-363F6F474D48.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700543551-TOZLP3W3EQ99G2LR92Q8/2B4913E7-C856-443B-A2A4-FCE021683CA0.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700541821-LKKDXRPPSK1OSYEWSDCP/811ECCB9-C936-452A-BB0F-020F45247B70.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700542515-K15UEE32VFDZL706EK2Y/084C6174-6DF7-4FD5-89C4-48965716E1F9.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700541134-6HU73JUHUSSYTLAXE38D/5522BDBB-BB88-4094-B609-44E60B0C7EB3.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700641895-M0231NS5JH2STGBYMFYH/EF07F4FC-6DD2-452A-8173-9D236234069B.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700643855-PVGW0SSCCLM9WIFMIBQU/C1A74960-5BAF-4D4C-A624-243D01869FB9.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700643239-AJJDWC5J6GIIIF9PL3IS/BAACE209-4C34-4E7E-AAA9-4CADEE6EEFFD.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/9e5e9748-bcd9-404d-8194-e03011194ca0/DF5EEC06-4C45-46B9-9207-C9B762183DBD.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/ef1x6crmq5q4l2dpl8rucnmej7mo6b","externalId":"squarespace:69d70a1f6892561c57b59a3e","priceCents":4350000}'::jsonb, '35edcad9b0b3615bf96883b8ad601513bc303ace6b95d8b84d7451777045488a', '92bd5d2cde7a70ded9414f9b0595c727e000f412218b4ccd397a26bb4d7d1c84', true, false, '{"year":1920,"brand":"Audemars Piguet","model":"Perpetual Calendar","style":"pocket","caliber":null,"has_box":null,"winding":null,"currency":"USD","brand_key":"audemarspiguet","condition":null,"reference":null,"dial_color":null,"has_papers":null,"description":"This rare masterpiece by Audemars Piguet is a perpetual calendar pocket watch from the 1920s, crafted in an 18K white gold case. It features a hand carved dial with applied Breguet numerals and displays information for day, date, month, phase of the moon, and leap year.","price_cents":4350000,"case_size_mm":46,"case_material":"white_gold","complications":["date","day_date","moonphase","perpetual_calendar"]}'::jsonb, '35edcad9b0b3615bf96883b8ad601513bc303ace6b95d8b84d7451777045488a', null, null, null, null, '2026-09-14T15:48:11.951285+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('f7d9fba6-38f6-401e-bdb8-ffdc2df1067f', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a4fe3f94c53b157280f179b', 'https://www.goldfingersvintage.com/watches/p/1980s-audemars-piguet-quantieme-perpetual-pocket-watch-ref-5555ba', '{"text":"A marvelous 1980s Audemars Piguet Quantieme Perpetual Pocket Watch ref. 5555BA in a heavy stepped 45mm solid 18K yellow gold case, with a lacquered white dial which appears almost porcelain-esque, with Roman numerals, day, date, month, Moonphase and leap year complication, powered by the meticulously finished AP cal. 5020/2820. \nAccording to the AP Chronicles, only 200 of these calibers were produced with the perpetual calendar module from its introduction in 1982 making this pocket even more scarce than its standard cal. 5020 bearing siblings. \nTo produce a pocket watch, and a complicated one at that, during the throes of the quartz revolution proves that being contrarian can yield rewarding results.","title":"1980''s Audemars Piguet Quantieme Perpetuel Pocket Watch ref. 5555BA","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0489e201-b0d8-4c84-9add-56afedb9069d/B0003448.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/cf099fb3-0ca1-4f19-b679-0254bf199aaa/B0003422.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/739ef97e-d81e-41a3-9965-79679b0f5978/B0003453.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/41345ebc-c286-42ed-af3a-cd280e32bfa2/B0003476.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e457b06c-250b-44da-abcf-b1b42c39fa04/B0003490.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/69508f5b-c21d-4389-821a-f1e965589125/B0003437.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/3ba826ab-35eb-468f-b547-3a57c2c4acb9/B0003499.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/3af461df-33a1-4484-8aeb-96ab8fa24a47/B0003493.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/77cb0e2d-99a7-43c7-9ac1-9be6d21c135c/B0003462.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1980s-audemars-piguet-quantieme-perpetual-pocket-watch-ref-5555ba","externalId":"squarespace:6a4fe3f94c53b157280f179b","priceCents":2649500}'::jsonb, '6098afd6d8ae7d780a32fcd60e63650f3df6dfbac1c257b482d2b54523a09753', '91861fd95eea2e9e65cbf93cfaa54e458f80c6cb0ed586364fb68c6bb1ee2f83', true, false, '{"year":1980,"brand":"Audemars Piguet","model":"Quantieme Perpetuel","style":"pocket","caliber":"cal. 5020/2820","has_box":null,"winding":null,"currency":"USD","brand_key":"audemarspiguet","condition":null,"reference":"5555BA","dial_color":"white","has_papers":null,"description":"This is a 1980s Audemars Piguet Quantieme Perpetual Pocket Watch ref. 5555BA in an 18K yellow gold case with a white dial featuring Roman numerals and multiple complications including day, date, month, Moonphase, and leap year.","price_cents":2649500,"case_size_mm":45,"case_material":"yellow_gold","complications":["date","day_date","moonphase"]}'::jsonb, '6098afd6d8ae7d780a32fcd60e63650f3df6dfbac1c257b482d2b54523a09753', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
