e.com/watches/p/1940s-jaeger-lecoultre-duo-date-half-sector-two-tone-dial","externalId":"squarespace:69fa7955f691fe20c13beb6c","priceCents":899500}'::jsonb, '9536c8f3bca2c45298ead5395b1d3550a3312991f855a3e7911407568ceca785', '4ef9494ac8f4276294de863fe97a9d4bddf6d1672553421f750798afab1488c8', true, false, '{"year":1940,"brand":"Jaeger-LeCoultre","model":"Duo Date","style":"dress","caliber":"JLC","has_box":null,"winding":"manual","currency":"USD","brand_key":"jaegerlecoultre","condition":null,"reference":null,"dial_color":null,"has_papers":null,"description":"This is a rare 1940s Jaeger-LeCoultre Duo Date in a 30mm stainless steel case with a two tone half-sector dial. It features a manual movement and is paired with a period correct Gay Freres ladder style bracelet.","price_cents":899500,"case_size_mm":30,"case_material":"two_tone","complications":["date"]}'::jsonb, '9536c8f3bca2c45298ead5395b1d3550a3312991f855a3e7911407568ceca785', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('e2d7d733-8e83-40c2-8582-4f86c0f9220b', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69f8d799cfa3e81e12d6688c', 'https://www.goldfingersvintage.com/watches/p/1970s-piaget-petite-oval-red-tiger-eye-onyx-stone-dial-18k-yg', '{"text":"A gorgeous 1970s Piaget Oval ladies dress watch in a sharp and likely unpolished 25x20mm 18K yellow gold case with a rare red tiger eye and onyx stone plank dial laid out like Tetris pieces with no cracks, powered by the famous ultra thin manually wound Piaget 9P caliber, with its original Piaget strap and 18K yellow gold signed buckle.","title":"1970''s Piaget Petite Oval Red Tiger Eye & Onyx Stone Dial 18K YG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/2280fe77-af6a-4173-a10f-b1cd61dc141b/DSC00978.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5e96071b-5124-4114-b1ec-55eae72c2a27/DSC01007.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f1badb3d-66a3-4d5e-88e7-8feb557e3256/DSC01009.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a76abd2b-f76d-49c3-bff8-44bc18dcd4c5/DSC01021.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/756a60df-4048-4d8c-8240-2adebfb5e2aa/DSC01029.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/12b12699-2adf-4bf2-96d6-22d8b22d8233/DSC01035.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1970s-piaget-petite-oval-red-tiger-eye-onyx-stone-dial-18k-yg","externalId":"squarespace:69f8d799cfa3e81e12d6688c","priceCents":799500}'::jsonb, '64af78a8f90d3cf3bfe689457dc6322ad345fbaf495f1ae20b537429a76c5879', '51ecb6058d26e32b67edc6f1b29db9c9b86507d5e5609eb8caf1ddcc2f1ed9fd', true, false, '{"year":1970,"brand":"Piaget","model":"Petite Oval","style":"dress","caliber":"Piaget 9P","has_box":null,"winding":"manual","currency":"USD","brand_key":"piaget","condition":null,"reference":null,"dial_color":"other","has_papers":null,"description":"This 1970s Piaget Oval ladies dress watch features a unique red tiger eye and onyx stone dial and is powered by the manually wound Piaget 9P caliber.","price_cents":799500,"case_size_mm":25,"case_material":"yellow_gold","complications":[]}'::jsonb, '64af78a8f90d3cf3bfe689457dc6322ad345fbaf495f1ae20b537429a76c5879', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('e8ef3e89-268b-4836-8c5e-7f541dd9ce73', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a31dc94dbedb812c32c76e9', 'https://www.goldfingersvintage.com/watches/p/1950s-vacheron-constantin-three-tone-sector-dial-pocket-watch-18k-rg', '{"text":"A spectacular 1950s Vacheron Constantin pocket watch in a slim yet large 48mm solid 18K rose gold case and an absolutely stunning three-tone half sector dial with applied rose Roman numerals, champlev&eacute; signature and minute tracks with perfect relief, and powered by a beautifully finished Vacheron caliber which is running well and keeping accurate time.","title":"1950''s Vacheron Constantin Three-Tone Sector Dial Pocket Watch 18K RG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c278edab-058f-4629-b2ae-ecc37c18fa8d/B0002120.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/42a4f335-4ca0-44c2-b321-0d9f113094fa/B0002120.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5d71aa7b-fd74-452f-84a1-e37a9b8a2f56/B0002115.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6837f53b-6446-478b-b8c9-99ade9212738/B0002142.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b5b7d772-6069-40fa-88df-333f3450d682/B0002116.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d48128d0-0ed4-4e35-85e7-8d8a694b9dc0/B0002105.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/380be1a4-a3e8-4c58-a457-4ea18c3fac10/B0002129.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1950s-vacheron-constantin-three-tone-sector-dial-pocket-watch-18k-rg","externalId":"squarespace:6a31dc94dbedb812c32c76e9","priceCents":899500}'::jsonb, '0da67c384ff44708c42504e8c4c4a47a8af7851f6b5418880192f0d335c8b504', 'd6521c311d42