  ('3702b2cd-b63b-45a5-b8f9-6b1a6093e0a2', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a0df78268dc3c55cb48a4f7', 'https://www.goldfingersvintage.com/watches/p/1930s-eberhard-pre-extra-fort-w-black-gilt-dial', '{"text":"A super dope 1930s Eberhard Pre-Extra Fort Chronograph in a large and sharp 40mm stepped case with a crazy black gilt dial adorned with snail and tachometer scales, powered by the Eberhard caliber 16000, a modified version of the Valjoux 65, to function as a monopusher at the top, with a slide to lock “pusher” at the bottom. \nRunning and functioning well, we do not have service history.","title":"1930''s Eberhard Pre-Extra Fort w/ Black Gilt Dial","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1b353607-a522-4ac6-88bf-c5f90c53ffc6/B0000453.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a625e5ff-6f0e-4377-8acb-1b61eb6d8e52/B0000473.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f7d1a816-cf78-47a8-b43f-c14dd360829c/B0000465.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/030c7a4d-e25d-492b-98c4-5f1670b250b0/B0000487.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0f3e8a2b-b5f2-48a9-9f67-87b9f3e17217/B0000491.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4af1b891-b160-47ad-9687-5826a6a636b7/B0000496.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6dab8238-f443-4629-be8b-501e749fadeb/B0000499.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/2d341e0d-63be-4c8c-b487-c667c4a365d2/B0000502.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f461353c-6d6b-4a3f-87bd-807a8e0d438b/B0000504.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1930s-eberhard-pre-extra-fort-w-black-gilt-dial","externalId":"squarespace:6a0df78268dc3c55cb48a4f7","priceCents":null}'::jsonb, '8b4791386fdf62357764a2661937dcdbd0352512b688083ff5fce41094d9f958', '3309855582360d717f41651194573b1f12ea4185a1313a5427e7cf9527f408a2', true, false, '{"year":1930,"brand":"Eberhard","model":"Pre-Extra Fort","style":"chronograph","caliber":"Eberhard 16000","has_box":null,"winding":"manual","currency":"USD","brand_key":"eberhard","condition":null,"reference":null,"dial_color":"black","has_papers":null,"description":"This is a 1930s Eberhard Pre-Extra Fort Chronograph in a large and sharp 40mm stepped case with a black gilt dial. It is powered by the Eberhard caliber 16000, a modified version of the Valjoux 65.","price_cents":null,"case_size_mm":40,"case_material":"other","complications":["chronograph"]}'::jsonb, '8b4791386fdf62357764a2661937dcdbd0352512b688083ff5fce41094d9f958', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-14T15:48:11.734+00:00'),
  ('d6d3ab09-5a20-4995-b7b2-9ec2e3f950a4', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69f3aede2f83637c43a45750', 'https://www.goldfingersvintage.com/watches/p/1940s-longines-chronostop-chronograph-lnos-10k-gf', '{"text":"A nearly mint and extremely handsome 1940s Longines Chronostop Chronograph in a sharp 10K gold filled 31mm case, broad faceted lugs and a nearly flawless applied Breguet numeral dial, its matching and likely original gold filled Longines signed buckle. \nThis ingenious take on the chronograph is unlike most, with its chronograph seconds designed to constantly run, its minute timing blue steeled hand vertically aligned. This allows for a completely symmetrical dial layout. And before you say “I will find one in solid gold” - they did not make them. Gold filled examples are the only way into one of these, and without hyperbole, this is the nicest one to exist. Period. \nIt comes with a period correct Longines box as well. We do not have service history but this watch is running and functioning well.","title":"1940''s Longines Chronostop Chronograph \"LNOS\" 10K GF","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/9f8c3467-cb6b-43e0-8167-ad8b801b2e88/DSC00871.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7a671ee5-be77-4ba9-9667-8fb1c24b4b48/DSC00925.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/85614213-7c00-47aa-9478-761498a348f8/DSC00877.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d6ba720a-4b78-4820-b564-da24b1ed9e5e/DSC00891.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6122fda2-2023-4c74-b4de-02992ee1782f/DSC00916.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/14629ab3-25bc-45cb-8bf8-f139f5da5141/DSC00929.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7cf1ce2f-9013-4349-9ff1-fb5042af865c/DSC00930.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c7911143-b075-41a3-aa58-6271fde36f68/DSC00935.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/cf440479-ac83-4743-a347-458769791a29/DSC00941.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/8a975d7a-7d78-48c0-9ec6-78406afb3ec6/DSC00961.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c85522f1-2b98-4db6-965d-a8f492e8b27d/DSC00965.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1940s-longines-chronostop-chronograph-lnos-10k-gf","externalId":"squarespace:69f3aede2f83637c43a45750","priceCents":699500}'::jsonb, '8684e3116ac49d45907b4015d890c8e857bef9c10ab88ed0c2d23f13266a4f97', 'db67f0a9d317d38eb8d0549842a0f968478da2ef1b016a9ffbe020dee8f12568', true, false, '{"year":1940,"brand":"Longines","model":"Chronostop","style":"chronograph","caliber":null,"has_box":true,"winding":null,"currency":"USD","brand_key":"longines","condition":"nearly mint","reference":null,"dial_color":"other","has_papers":null,"description":"A nearly mint and extremely handsome 1940s Longines Chronostop Chronograph in a sharp 10K gold filled case, featuring a nearly flawless applied Breguet numeral dial. This unique chronograph allows for a symmetrical dial layout with a constantly running seconds hand.","price_cents":699500,"case_size_mm":31,"case_material":"yellow_gold","complications":["chronograph"]}'::jsonb, '8684e3116ac49d45907b4015d890c8e857bef9c10ab88ed0c2d23f13266a4f97', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('70ca596c-cb26-4d29-a7be-25eeb81d4585', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:68f69a35947a864d0948aa38', 'https://www.goldfingersvintage.com/watches/p/1960s-eberhard-scafograf-300-diver-ref-26013', '{"text":"A rugged and amazing example of the Eberhard Scafograf 300 Diver ref. 26013 from the 1960s, with a very sharp 42mm case featuring signature brushed and beveled twisted lugs, flat satin brushed mid case, and a glossy black dial with beautifully aged and matching lume, and powered by the automatic Eberhard caliber 250-123. \nBeyond the Submariner, Omega Diver 300, Blancpain and countless others, the Eberhard Scafograf 300 was the diver of choice for the ones who went against the grain. With unidirectional rotating aluminum bezel, glossy black dial, this purpose built tool watch shows its age and use with grace, having never been polished; each ding shows a life lived with respect which what a watch like this should look like after 65 years. \nWhat’s more this comes paired on an Eberhard signed Unroc buckle. Keeping time and running well. We do not have service history.","title":"1960''s Eberhard Scafograf 300 Diver ref. 26013","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/29a44863-8f34-4dcf-b974-15e1e6c4c098/DSC00998.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ffb0a29a-d089-49fc-8a6e-8d831d28762f/DSC01016.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/05b22077-11d5-4058-b9c4-ff9582df1a32/DSC01006.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a6162df1-8f15-4e2c-b022-e4c95582c3db/DSC01027.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c989a5f7-77c9-47a7-bfba-e1ba54d5bc91/DSC01034.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/72544a60-3cb8-434f-92