  ('ac488af5-1ab4-43ee-b5b7-194de6f1ac75', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:67d45166ab754663f48c95aa', 'https://www.goldfingersvintage.com/watches/p/1980s-corum-skeleton-dress-watch-factory-diamond-18k-wg', '{"text":"A spectacular 1980s Corum Skeletonized Dress Watch in 18K white gold, with a beautiful chapter ring factory set with diamonds, hand engraved bridges and stunningly organized architecture based on the Audemars Piguet caliber 2003. \nThe case measures a charming 30mm, 32mm with crown and 38mm lug to lug. \nComes with its original steel Corum buckle. \nThe manual wind caliber is running well.","title":"1980''s Corum Skeleton Dress Watch Factory Diamond 18K WG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6ed0355b-7a31-499e-9fd5-7156c2b40988/DSC03967.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6a432e39-a505-4fc0-86d6-671cbbcf7ea6/DSC03982.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5f4563eb-96d8-4683-a96c-b7ac241575b2/DSC03994.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/90c0f315-79f8-4387-8b18-635de973632c/DSC04007.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e321a951-0a35-4665-93ba-c3ea772b554c/DSC04021.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/255348ba-60b3-40ad-956e-580ed0ec9027/DSC04034.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c91ea3ec-f1b2-4be7-8a77-6b65a38598ec/DSC04037.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1980s-corum-skeleton-dress-watch-factory-diamond-18k-wg","externalId":"squarespace:67d45166ab754663f48c95aa","priceCents":1099500}'::jsonb, '84fb91c031e98717b3162b24b07fc971f67d185fa8fc08564013a3fd8f583a23', 'b8667e0935bb95f5e88