  ('181337ed-386e-45c5-9ed3-5a1c8df90048', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a592426d0719241db2825b0', 'https://www.goldfingersvintage.com/watches/p/1930s-patek-philippe-two-tone-half-sector-dial-pocket-watch-18k-yg-w-extract', '{"text":"A marvelous 1930s Patek Philippe Pocket Watch made for the French market, with a silvered two-tone half sector dial with applied Arabic and rectangular indices, it’s champlev&eacute; details immaculately preserved, with subtly raised and hand carved enamel work including its long French signature, circular inner minute track and its outer as well, in a 45mm 18K yellow gold case, powered by a gorgeous Patek caliber which is running well and keeping accurate time. \nThis watch comes with its Extract from the Archives confirming its date of manufacture to 1930 and subsequent sale in 1939. Sold in France as noted by its “Fab Suisse” designation at six o’clock and multiple Owl hallmarks, the French code for imported gold, this magnificent object comes from the days the firm was crafting works of art and retains every iota of beauty that left the manufacturer back in 1930.","title":"1930''s Patek Philippe Two-Tone Half-Sector Dial Pocket Watch 18K YG w/ Extract","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/596e15ad-bcd5-49ca-bbd0-7cfa1076e86f/B0003799.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ee5516d2-0386-4217-9605-b1cabb9972e6/B0003811.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d7ae9b45-14f3-4c8d-bd2b-2ad9a70ff4f1/B0003863.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b8e42b6d-2132-45b1-972e-4639731ef9f1/B0003885.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/2a2cae03-bf0a-4070-9c0e-b92174be1658/B0003875.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f07ea12e-43c2-4953-9e58-9c1c8ae8523a/B0003872.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0b36ada3-5af7-424d-b902-5a7e0c758099/B0003854.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/14bda5c3-2623-44d0-881d-577fc5fc12e4/B0003851.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0dcbc2e0-540f-4338-9d9b-0d0ffd9f435b/B0003807.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1930s-patek-philippe-two-tone-half-sector-dial-pocket-watch-18k-yg-w-extract","externalId":"squarespace:6a592426d0719241db2825b0","priceCents":1899500}'::jsonb, '67a8b56f154f98197e608c8549c45ff2ebee4e4d9399831fdf23b54c2873a74d', '87c1e9d998d85ee29edf78b3d758443256518b137c15fcde93a7214f50ede35e', true, false, '{"year":1930,"brand":"Patek Philippe","model":null,"style":"other","caliber":"Patek caliber","has_box":null,"winding":null,"currency":"USD","brand_key":"patekphilippe","condition":null,"reference":null,"dial_color":"silver","has_papers":null,"description":"A marvelous 1930s Patek Philippe Pocket Watch made for the French market, with a silvered two-tone half sector dial and a 45mm 18K yellow gold case. This watch comes with its Extract from the Archives confirming its date of manufacture to 1930.","price_cents":1899500,"case_size_mm":45,"case_material":"yellow_gold","complications":[]}'::jsonb, '67a8b56f154f98197e608c8549c45ff2ebee4e4d9399831fdf23b54c2873a74d', null, null, null, null, '2026-09-14T15:48:11.878242+00:00', '2026-09-16T06:26:49.887+00:00'),
  ('15497b38-5b3b-4953-ac4c-b85c93161ed4', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a07c16c9bbeeb1bb610c24c', 'https://www.goldfingersvintage.com/watches/p/1940s-movado-curviplan-tank-w-two-tone-sector-dial', '{"text":"A beautiful 1940s Movado Curviplan in a large 40x23mm curved stainless steel case with a very rare two-tone sector dial, retaining its crisp and clear printing, its case sharp with broad bevels in tact, contrasted by even vertical satin brushing across its midcase and bezel, powered by the Movado caliber 510, which has just been serviced and is running well.","title":"1940''s Movado Curviplan Tank w/ Two-Tone Sector Dial","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c146c41b-254b-4b24-9746-3a7ffa143af9/DSC01917.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/fd6bdfd5-e9bd-40fd-bae7-364707928140/DSC01923.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/193df6c0-8137-47b0-81c8-18d15b53d5de/DSC01928.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/efb1db44-f7d9-441a-96a4-dcf5c728ef46/DSC01938.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/9f5c882a-63b1-44d2-9dba-53bf4b8bab47/DSC01943.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/9324e1c5-cd76-44de-969b-6bf16755dccf/DSC01947.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d24c50f1-0535-4698-a654-c991ec846045/DSC01958.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/cff955d2-c78f-4622-8185-d7d513eae444/DSC01970.jpg?format=1500w"],"sourceUrl":"https://www.goldfingersvintage.com/watches/p/1940s-movado-curviplan-tank-w-two-tone-sector-dial","externalId":"squarespace:6a07c16c9bbeeb1bb610c24c","priceCents":799500}'::jsonb,